"_id\":\"5368391\"},{\"tab_title\":\"I am having an issue with paying at checkout.\",\"tab_content\":\"<p>If you experience problems with ordering on our website, it may be because you are trying to pay with a card issuer or payment method that we currently do not support. If none of these are applicable, please check with your bank to make sure your card supports international purchases.<br \\/><br \\/>If you have further problems, please contact our customer service.<\\/p>\",\"_id\":\"b151e87\"}],\"selected_icon\":{\"value\":\"vamtamtheme- vamtam-theme-arrow-down\",\"library\":\"theme-icons\"},\"selected_active_icon\":{\"value\":\"vamtamtheme- vamtam-theme-arrow-top\",\"library\":\"theme-icons\"},\"border_width\":{\"unit\":\"px\",\"size\":1,\"sizes\":[]},\"border_color\":\"#0000001A\",\"title_typography_typography\":\"custom\",\"title_typography_font_family\":\"Montserrat\",\"title_typography_font_size\":{\"unit\":\"px\",\"size\":20,\"sizes\":[]},\"title_typography_font_size_mobile\":{\"unit\":\"px\",\"size\":17,\"sizes\":[]},\"title_typography_font_weight\":\"400\",\"title_typography_text_transform\":\"uppercase\",\"title_typography_line_height\":{\"unit\":\"em\",\"size\":1.4,\"sizes\":[]},\"title_typography_line_height_mobile\":{\"unit\":\"em\",\"size\":1.2,\"sizes\":[]},\"title_padding\":{\"unit\":\"px\",\"top\":\"30\",\"right\":\"0\",\"bottom\":\"30\",\"left\":\"0\",\"isLinked\":false},\"icon_align\":\"right\",\"icon_space\":{\"unit\":\"px\",\"size\":0,\"sizes\":[]},\"content_padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"15\",\"left\":\"0\",\"isLinked\":false},\"_border_border\":\"solid\",\"_border_width\":{\"unit\":\"px\",\"top\":\"1\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"__globals__\":{\"title_typography_typography\":\"globals\\/typography?id=4421a3e\",\"border_color\":\"globals\\/colors?id=vamtam_accent_7\",\"tab_active_color\":\"\",\"title_color\":\"\",\"title_background\":\"\",\"_border_color\":\"gl