  `taxable_amount` double NOT NULL DEFAULT 0,
  PRIMARY KEY (`order_id`,`tax_rate_id`,`order_item_id`),
  KEY `tax_rate_id` (`tax_rate_id`),
  KEY `date_created` (`date_created`)
