  KEY `product_status_attempt` (`product_id`,`status`,`date_last_attempt_gmt`,`id`),
  KEY `user_lookup` (`user_id`,`product_id`,`status`),
  KEY `email_lookup` (`user_email`,`product_id`,`status`)
